//! G02 end-to-end vectors (`ffw-ld0`).
//!
//! `tests/g02/vectors.json` is generated by the independent Python reference model
//! (`tests/g02/generate.py`), never by this crate. This executor runs every vector through the public
//! API (the real `MemberVolume`, `GroupVolume`, `RolePlan` and a real D02 `ProtectedBoardDsp`) and
//! prints one `G02-OBSERVED {json}` line per case for the Python judge
//! (`tests/g02/run_cases.py --judge`). It also compares each observation with the vector's `expect`
//! itself, so a divergence fails `cargo test` and not only the judge.
//!
//! Run with `cargo test -p franken-dsp --test g02_vectors -- --nocapture`. Override the vector path
//! with `FFW_G02_VECTORS`.

use franken_board_profile::{BoardProfile, TransducerRole, synthetic_test_fixture_catalog};
use franken_dsp::StereoAudioBlock;
use franken_dsp::protection::{
    Admission, BoardStatus, FaultCode, ProtectedBoardDsp, ProtectedOutput, ProtectionError,
    synthetic_calibration_for,
};
use franken_dsp::volume::{
    GroupSnapshot, GroupVolume, MemberResult, MemberVolume, PersistedMember, Role, RolePlan, Stamp,
    VolumeCommand, VolumeError,
};
use serde_json::{Map, Value, json};

/// The reference model emulates f32 operation by operation, so values agree to the last bit; this
/// allows one ulp near 1.0 and is far below any behavioural difference.
const TOLERANCE: f64 = 1.0e-7;

const ROLES: [(&str, Role); 4] = [
    ("stereo", Role::Stereo),
    ("left", Role::Left),
    ("right", Role::Right),
    ("sub", Role::Sub),
];

fn field<'a>(value: &'a Value, key: &str) -> &'a Value {
    value
        .get(key)
        .unwrap_or_else(|| panic!("vector field `{key}` is missing"))
}

fn str_of<'a>(value: &'a Value, key: &str) -> &'a str {
    field(value, key)
        .as_str()
        .unwrap_or_else(|| panic!("vector field `{key}` is not a string"))
}

fn u64_of(value: &Value, key: &str) -> u64 {
    field(value, key)
        .as_u64()
        .unwrap_or_else(|| panic!("vector field `{key}` is not an unsigned integer"))
}

fn bool_of(value: &Value, key: &str) -> bool {
    field(value, key)
        .as_bool()
        .unwrap_or_else(|| panic!("vector field `{key}` is not a boolean"))
}

fn arg(items: &[Value], index: usize) -> &Value {
    items
        .get(index)
        .unwrap_or_else(|| panic!("operation is missing argument {index}: {items:?}"))
}

fn u64_at(items: &[Value], index: usize) -> u64 {
    arg(items, index)
        .as_u64()
        .unwrap_or_else(|| panic!("argument {index} is not an unsigned integer: {items:?}"))
}

fn u8_at(items: &[Value], index: usize) -> u8 {
    u8::try_from(u64_at(items, index)).unwrap_or_else(|_| panic!("argument {index} is not a u8"))
}

fn u32_at(items: &[Value], index: usize) -> u32 {
    u32::try_from(u64_at(items, index)).unwrap_or_else(|_| panic!("argument {index} is not a u32"))
}

fn i16_at(items: &[Value], index: usize) -> i16 {
    let n = arg(items, index)
        .as_i64()
        .unwrap_or_else(|| panic!("argument {index} is not an integer: {items:?}"));
    i16::try_from(n).unwrap_or_else(|_| panic!("argument {index} is not an i16"))
}

fn bool_at(items: &[Value], index: usize) -> bool {
    arg(items, index)
        .as_bool()
        .unwrap_or_else(|| panic!("argument {index} is not a boolean: {items:?}"))
}

fn ops_of(case: &Value) -> &[Value] {
    field(case, "ops").as_array().expect("ops is an array")
}

fn items_of(op: &Value) -> &[Value] {
    op.as_array().expect("an operation is an array")
}

fn fixture(model: &str) -> BoardProfile {
    synthetic_test_fixture_catalog()
        .into_iter()
        .find(|profile| profile.model_number == model)
        .unwrap_or_else(|| panic!("no synthetic fixture board `{model}`"))
}

/// A ceiling is a number, or the strings "nan"/"inf" because JSON has no non-finite numbers.
fn ceiling_of(value: &Value) -> f32 {
    match value {
        Value::String(text) => match text.as_str() {
            "nan" => f32::NAN,
            "inf" => f32::INFINITY,
            other => panic!("unknown ceiling literal `{other}`"),
        },
        other => other.as_f64().expect("a ceiling is a number") as f32,
    }
}

fn command_of(raw: &Value) -> VolumeCommand {
    let items = items_of(raw);
    let name = items[0].as_str().expect("command name");
    match name {
        "set_volume" => VolumeCommand::SetVolume(u8_at(items, 1)),
        "adjust_volume" => VolumeCommand::AdjustVolume(i16_at(items, 1)),
        "set_trim" => VolumeCommand::SetTrim(
            u16::try_from(u64_at(items, 1)).unwrap_or_else(|_| panic!("trim is not a u16")),
        ),
        "reset_trim" => VolumeCommand::ResetTrim,
        "set_group_mute" => VolumeCommand::SetGroupMute(bool_at(items, 1)),
        other => panic!("unknown command `{other}`"),
    }
}

fn code<T>(result: Result<T, VolumeError>) -> &'static str {
    match result {
        Ok(_) => "ok",
        Err(error) => error.code(),
    }
}

fn mute_name(member: &MemberVolume) -> Value {
    member
        .effective_mute()
        .map_or(Value::Null, |reason| json!(reason.name()))
}

fn state_json(member: &MemberVolume) -> Map<String, Value> {
    let state = json!({
        "mute": mute_name(member),
        "desired": member.desired_volume(),
        "trim": member.trim_permille(),
        "epoch": member.epoch(),
        "revision": member.last_revision(),
        "unmuted": f64::from(member.unmuted_gain()),
        "gain": f64::from(member.output_gain()),
    });
    state.as_object().expect("object").clone()
}

// ---- gain grid ------------------------------------------------------------------------------------------

fn run_gain_grid(case: &Value) -> Value {
    let mut member = MemberVolume::new(ceiling_of(field(case, "protection_ceiling")));
    member.declare_epoch(1).expect("declare");
    member.complete_join();
    let fault = field(case, "fault_ceiling");
    if !fault.is_null() {
        member.set_fault_ceiling(Some(ceiling_of(fault)));
    }
    let mut revision = 0;
    let mut gains = Vec::new();
    for row in field(case, "rows").as_array().expect("rows") {
        let row = items_of(row);
        let volume = u8_at(row, 0);
        let trim = u16::try_from(u64_at(row, 1)).expect("trim is a u16");
        for command in [
            VolumeCommand::SetVolume(volume),
            VolumeCommand::SetTrim(trim),
        ] {
            revision += 1;
            member
                .apply(Stamp { epoch: 1, revision }, command)
                .expect("a grid row is a valid command");
        }
        gains.push(f64::from(member.unmuted_gain()));
    }
    json!({ "gains": gains })
}

// ---- roles --------------------------------------------------------------------------------------------------

/// The profile a roles vector describes. A fixture entry is cross-checked against the real catalog,
/// so a drifted fixture is reported instead of silently agreeing with itself.
fn layout_profile(layout: &Value) -> Result<BoardProfile, String> {
    let routing: Vec<TransducerRole> =
        serde_json::from_value(field(layout, "routing").clone()).map_err(|e| e.to_string())?;
    let channels = u8::try_from(u64_of(layout, "hardware_channels")).map_err(|e| e.to_string())?;
    match layout.get("fixture").and_then(Value::as_str) {
        Some(model) => {
            let profile = fixture(model);
            if profile.channel_routing != routing || profile.hardware_channels != channels {
                return Err(format!(
                    "fixture `{model}` is {} channels {:?}, the vector says {channels} channels {routing:?}",
                    profile.hardware_channels, profile.channel_routing
                ));
            }
            Ok(profile)
        }
        None => {
            let mut profile = fixture(str_of(layout, "base"));
            profile.channel_routing = routing;
            profile.hardware_channels = channels;
            Ok(profile)
        }
    }
}

fn run_roles(case: &Value) -> (Value, Option<String>) {
    let profile = match layout_profile(field(case, "layout")) {
        Ok(profile) => profile,
        Err(message) => return (json!({ "results": {} }), Some(message)),
    };
    let mut results = Map::new();
    for (name, role) in ROLES {
        let text = match RolePlan::for_profile(&profile, role) {
            Ok(_) => "ok",
            Err(VolumeError::RoleUnavailable { reason, .. }) => reason.name(),
            Err(other) => other.code(),
        };
        results.insert(name.to_string(), json!(text));
    }
    (json!({ "results": results }), None)
}

fn run_role_map(case: &Value) -> (Value, Option<String>) {
    let samples: Vec<(f32, f32)> = field(case, "samples")
        .as_array()
        .expect("samples")
        .iter()
        .map(|pair| {
            let pair = items_of(pair);
            (
                pair[0].as_f64().expect("left") as f32,
                pair[1].as_f64().expect("right") as f32,
            )
        })
        .collect();
    let (stereo_board, sub_board) = (fixture("S5"), fixture("Sub"));
    let mut mapped = Map::new();
    let mut problem = None;
    for (name, role) in ROLES {
        let board = if role == Role::Sub {
            &sub_board
        } else {
            &stereo_board
        };
        let plan = RolePlan::for_profile(board, role).expect("the role exists on this fixture");
        let pairs: Vec<(f32, f32)> = samples.iter().map(|&(l, r)| plan.map(l, r)).collect();

        // The block form must agree with the per-sample form.
        let mut input = StereoAudioBlock::silence(0);
        input.frames = samples.len();
        for ((left, right), &(l, r)) in input
            .left
            .iter_mut()
            .zip(input.right.iter_mut())
            .zip(&samples)
        {
            (*left, *right) = (l, r);
        }
        let mut block = StereoAudioBlock::silence(0);
        plan.map_block(&input, &mut block);
        let block_pairs: Vec<(f32, f32)> = block
            .left
            .iter()
            .copied()
            .zip(block.right.iter().copied())
            .take(block.frames)
            .collect();
        if block_pairs != pairs {
            problem.get_or_insert_with(|| {
                format!("{name}: map_block {block_pairs:?} differs from map {pairs:?}")
            });
        }
        let json_pairs: Vec<Value> = pairs
            .iter()
            .map(|&(l, r)| json!([f64::from(l), f64::from(r)]))
            .collect();
        mapped.insert(name.to_string(), json!(json_pairs));
    }
    (json!({ "mapped": mapped }), problem)
}

// ---- member scripts -------------------------------------------------------------------------------------------

fn board_for(kind: &str) -> ProtectedBoardDsp {
    let profile = fixture("S3");
    match kind {
        "active" => {
            let calibration = synthetic_calibration_for(&profile);
            ProtectedBoardDsp::admit(&profile, Some(&calibration), Admission::HostSimulation)
        }
        "fail_muted" => ProtectedBoardDsp::admit(&profile, None, Admission::HostSimulation),
        other => panic!("unknown board kind `{other}`"),
    }
}

/// Render `frames` single frames of silence and summarize the applied-gain trajectory.
fn ramp(dsp: &mut ProtectedBoardDsp, frames: usize) -> Map<String, Value> {
    assert!(frames > 0, "a ramp needs at least one frame");
    let mut out = ProtectedOutput::new();
    let mut one = StereoAudioBlock::silence(0);
    one.frames = 1;
    let mut previous = f64::from(dsp.applied_gain());
    let (mut max_step, mut changes, mut last_sign) = (0.0f64, 0u32, 0i8);
    let (mut max_applied, mut min_applied) = (f64::NEG_INFINITY, f64::INFINITY);
    for _ in 0..frames {
        dsp.render_into(&one, &mut out);
        let now = f64::from(dsp.applied_gain());
        let delta = now - previous;
        max_step = max_step.max(delta.abs());
        let sign = if delta > 0.0 {
            1
        } else if delta < 0.0 {
            -1
        } else {
            0
        };
        if sign != 0 {
            if last_sign != 0 && sign != last_sign {
                changes += 1;
            }
            last_sign = sign;
        }
        max_applied = max_applied.max(now);
        min_applied = min_applied.min(now);
        previous = now;
    }
    let summary = json!({
        "max_step": max_step,
        "direction_changes": changes,
        "max_applied": max_applied,
        "min_applied": min_applied,
    });
    summary.as_object().expect("object").clone()
}

fn board_status(name: &str) -> BoardStatus {
    match name {
        "active" => BoardStatus::Active,
        "fail_muted" => BoardStatus::FailMuted(ProtectionError::NoCalibration),
        "faulted" => BoardStatus::Faulted(FaultCode::ThermalHard { channel: 0 }),
        other => panic!("unknown board status `{other}`"),
    }
}

fn run_member_script(case: &Value) -> Value {
    let ceiling = ceiling_of(field(case, "ceiling"));
    let mut member = match field(case, "start") {
        Value::String(text) if text == "new" => MemberVolume::new(ceiling),
        other => {
            let stored = field(other, "restore");
            MemberVolume::restore(
                PersistedMember {
                    volume: u8::try_from(u64_of(stored, "volume")).expect("volume is a u8"),
                    trim_permille: u16::try_from(u64_of(stored, "trim")).expect("trim is a u16"),
                    local_mute: bool_of(stored, "local_mute"),
                },
                ceiling,
            )
        }
    };
    let mut dsp = field(case, "board").as_str().map(board_for);
    let mut synced = false;
    let mut trace = Vec::new();
    for op in ops_of(case) {
        let items = items_of(op);
        let name = items[0].as_str().expect("operation name");
        let mut result = "ok";
        let mut duplicate = None;
        let mut extra = Map::new();
        match name {
            "declare" => result = code(member.declare_epoch(u64_at(items, 1))),
            "join" => member.complete_join(),
            "cmd" => {
                let stamp = Stamp {
                    epoch: u64_at(items, 1),
                    revision: u64_at(items, 2),
                };
                match member.apply(stamp, command_of(arg(items, 3))) {
                    Ok(receipt) => duplicate = Some(receipt.duplicate),
                    Err(error) => result = error.code(),
                }
            }
            "local_mute" => member.local_mute(bool_at(items, 1)),
            "local_trim" => result = code(member.local_trim_step(i16_at(items, 1))),
            "board" => {
                member.observe_board(board_status(arg(items, 1).as_str().expect("status name")))
            }
            "ceiling" => member.set_protection_ceiling(ceiling_of(arg(items, 1))),
            "fault_ceiling" => {
                let value = arg(items, 1);
                member.set_fault_ceiling((!value.is_null()).then(|| ceiling_of(value)));
            }
            "reconnect" => {
                result = code(member.reconnect(GroupSnapshot {
                    epoch: u64_at(items, 1),
                    revision: u64_at(items, 2),
                    master_volume: u8_at(items, 3),
                    group_mute: bool_at(items, 4),
                }));
            }
            "sync" => {
                let board = dsp.as_mut().expect("sync needs a board");
                result = match member.sync(board) {
                    Ok(()) => "ok",
                    Err(error) => error.code(),
                };
                synced = true;
            }
            "ramp" => {
                let board = dsp.as_mut().expect("ramp needs a board");
                extra = ramp(board, usize::try_from(u64_at(items, 1)).expect("frames"));
            }
            other => panic!("unknown member operation `{other}`"),
        }
        let mut entry = state_json(&member);
        entry.insert("op".to_string(), json!(name));
        entry.insert("result".to_string(), json!(result));
        if let Some(duplicate) = duplicate {
            entry.insert("duplicate".to_string(), json!(duplicate));
        }
        if let Some(board) = &dsp {
            let user = if synced {
                json!(f64::from(board.user_gain()))
            } else {
                Value::Null
            };
            entry.insert(
                "dsp".to_string(),
                json!({
                    "applied": f64::from(board.applied_gain()),
                    "muted": board.is_muted(),
                    "user": user,
                }),
            );
        }
        entry.extend(extra);
        trace.push(Value::Object(entry));
    }
    json!({ "trace": trace })
}

// ---- group scripts ----------------------------------------------------------------------------------------------

fn member_status(result: &MemberResult) -> &'static str {
    match result {
        MemberResult::Accepted(receipt) if receipt.duplicate => "duplicate",
        MemberResult::Accepted(_) => "accepted",
        MemberResult::Rejected(error) => error.code(),
        MemberResult::Missing => "missing",
    }
}

fn run_group_script(case: &Value) -> Value {
    let mut group = GroupVolume::new(u64_of(case, "epoch"));
    let mut ids: Vec<u32> = Vec::new();
    let mut trace = Vec::new();
    for op in ops_of(case) {
        let items = items_of(op);
        let name = items[0].as_str().expect("operation name");
        let mut result = "ok";
        let mut fanout: Option<Value> = None;
        match name {
            "add" => {
                let id = u32_at(items, 1);
                result = code(group.add_member(id, ceiling_of(arg(items, 2))));
                if result == "ok" {
                    ids.push(id);
                }
            }
            "join" => match group.member_mut(u32_at(items, 1)) {
                Some(member) => member.complete_join(),
                None => result = "unknown_member",
            },
            "present" => result = code(group.set_present(u32_at(items, 1), bool_at(items, 2))),
            "gcmd" => {
                let stamp = Stamp {
                    epoch: u64_at(items, 1),
                    revision: u64_at(items, 2),
                };
                match group.apply(stamp, command_of(arg(items, 3))) {
                    Ok(results) => {
                        let rows: Vec<Value> = results
                            .iter()
                            .map(|(id, r)| json!([id, member_status(r)]))
                            .collect();
                        fanout = Some(json!(rows));
                    }
                    Err(error) => result = error.code(),
                }
            }
            "rejoin" => result = code(group.rejoin(u32_at(items, 1))),
            "declare_member" => {
                result = match group.member_mut(u32_at(items, 1)) {
                    Some(member) => code(member.declare_epoch(u64_at(items, 2))),
                    None => "unknown_member",
                };
            }
            "local_mute" => match group.member_mut(u32_at(items, 1)) {
                Some(member) => member.local_mute(bool_at(items, 2)),
                None => result = "unknown_member",
            },
            other => panic!("unknown group operation `{other}`"),
        }
        let snapshot = group.snapshot();
        let state: Vec<Value> = ids
            .iter()
            .map(|&id| {
                let member = group.member(id).expect("a tracked member exists");
                json!([
                    id,
                    member.desired_volume(),
                    mute_name(member),
                    f64::from(member.output_gain()),
                    member.epoch()
                ])
            })
            .collect();
        let mut entry = json!({
            "op": name,
            "result": result,
            "snapshot": {
                "epoch": snapshot.epoch,
                "revision": snapshot.revision,
                "volume": snapshot.master_volume,
                "group_mute": snapshot.group_mute,
            },
            "state": state,
        });
        if let Some(rows) = fanout {
            entry["members"] = rows;
        }
        trace.push(entry);
    }
    json!({ "trace": trace })
}

// ---- comparison and driver -----------------------------------------------------------------------------------------

fn diff(path: &str, want: &Value, got: &Value) -> Option<String> {
    match (want, got) {
        (Value::Number(a), Value::Number(b)) => match (a.as_f64(), b.as_f64()) {
            (Some(x), Some(y)) if (x - y).abs() <= TOLERANCE => None,
            _ => Some(format!("{path}: expected {want}, observed {got}")),
        },
        (Value::Object(a), Value::Object(b)) => {
            if a.len() != b.len() || a.keys().any(|key| !b.contains_key(key)) {
                let (want_keys, got_keys): (Vec<_>, Vec<_>) =
                    (a.keys().collect(), b.keys().collect());
                return Some(format!(
                    "{path}: keys differ, expected {want_keys:?}, observed {got_keys:?}"
                ));
            }
            a.iter()
                .find_map(|(key, w)| diff(&format!("{path}.{key}"), w, &b[key]))
        }
        (Value::Array(a), Value::Array(b)) => {
            if a.len() != b.len() {
                return Some(format!(
                    "{path}: expected {} items, observed {}",
                    a.len(),
                    b.len()
                ));
            }
            a.iter()
                .zip(b)
                .enumerate()
                .find_map(|(i, (w, g))| diff(&format!("{path}[{i}]"), w, g))
        }
        _ if want == got => None,
        _ => Some(format!("{path}: expected {want}, observed {got}")),
    }
}

/// Observe one case. The second element is a structural problem in the vector itself.
fn observe(case: &Value) -> (Value, Option<String>) {
    match str_of(case, "kind") {
        "gain_grid" => (run_gain_grid(case), None),
        "roles" => run_roles(case),
        "role_map" => run_role_map(case),
        "member_script" => (run_member_script(case), None),
        "group_script" => (run_group_script(case), None),
        other => panic!("unknown vector kind `{other}`"),
    }
}

/// Observe and compare with the vector's `expect`.
fn run_case(case: &Value) -> (Value, Option<String>) {
    let (mut observed, structural) = observe(case);
    let problem = structural.or_else(|| {
        diff("", field(case, "expect"), &observed)
            .map(|message| format!("{}: {message}", str_of(case, "id")))
    });
    if let Some(map) = observed.as_object_mut() {
        map.insert("id".to_string(), json!(str_of(case, "id")));
        map.insert("kind".to_string(), json!(str_of(case, "kind")));
    }
    (observed, problem)
}

fn load_vectors() -> Value {
    let path = std::env::var("FFW_G02_VECTORS").unwrap_or_else(|_| {
        format!(
            "{}/../../tests/g02/vectors.json",
            env!("CARGO_MANIFEST_DIR")
        )
    });
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!("cannot read G02 vectors at {path}: {e} (generate: tests/g02/run_cases.py --write-vectors)")
    });
    let doc: Value = serde_json::from_str(&text).expect("vectors.json parses");
    assert_eq!(doc["schema"], "ffw.g02.vectors.v1");
    doc
}

#[test]
fn g02_vectors_match_the_independent_reference() {
    let doc = load_vectors();
    let cases = doc["cases"].as_array().expect("cases array");
    assert!(
        cases.len() >= 40,
        "suspiciously few vectors: {}",
        cases.len()
    );
    let mut failures: Vec<String> = Vec::new();
    for case in cases {
        let (observed, problem) = run_case(case);
        println!("G02-OBSERVED {observed}");
        if let Some(message) = problem {
            println!("G02-DIVERGENCE {message}");
            failures.push(message);
        }
    }
    println!(
        "G02-SUMMARY cases={} failures={}",
        cases.len(),
        failures.len()
    );
    assert!(
        failures.is_empty(),
        "{} of {} G02 vectors diverged from the reference; first: {}",
        failures.len(),
        cases.len(),
        failures[0]
    );
}

/// Control: the comparison is not vacuous. A planted wrong expectation must be reported, and the
/// unmodified vector must pass.
#[test]
fn a_planted_wrong_expectation_is_detected() {
    let doc = load_vectors();
    let cases = doc["cases"].as_array().expect("cases array");
    for kind in [
        "gain_grid",
        "roles",
        "role_map",
        "member_script",
        "group_script",
    ] {
        let case = cases
            .iter()
            .find(|c| str_of(c, "kind") == kind)
            .unwrap_or_else(|| panic!("a `{kind}` vector"));
        assert!(
            run_case(case).1.is_none(),
            "the unmodified {kind} vector must pass"
        );
        let mut corrupted = case.clone();
        let expect = corrupted["expect"].as_object_mut().expect("expect object");
        let (_, first) = expect.iter_mut().next().expect("expect is not empty");
        match first {
            Value::Array(items) => {
                // Flip a result/gain deep inside the first entry.
                let slot = items.first_mut().expect("a non-empty list");
                *slot = match slot.clone() {
                    Value::Object(mut entry) => {
                        entry.insert("result".to_string(), json!("planted_wrong"));
                        Value::Object(entry)
                    }
                    Value::Number(n) => json!(n.as_f64().unwrap_or(0.0) + 0.5),
                    other => json!([other, "planted_wrong"]),
                };
            }
            other => *other = json!({ "planted": "wrong" }),
        }
        assert!(
            run_case(&corrupted).1.is_some(),
            "a corrupted {kind} expectation must be detected"
        );
    }
}

/// The vectors assume D02's synthetic calibration ramps 10 ms (1/480 per sample). If that changes,
/// every ramp vector is stale, and this says so directly instead of as 20 confusing divergences.
#[test]
fn g02_assumes_the_d02_synthetic_ramp_is_ten_milliseconds() {
    let mut dsp = board_for("active");
    dsp.set_user_gain(1.0);
    dsp.set_muted(false).expect("an active board unmutes");
    let applied = ramp(&mut dsp, 1);
    let step = applied["max_applied"].as_f64().expect("applied");
    assert!(
        (step - 1.0 / 480.0).abs() < 1.0e-9,
        "D02's synthetic ramp step is {step}, the G02 vectors assume {}",
        1.0 / 480.0
    );
}
